def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    recs = inp.get('records')
    if not isinstance(recs, list):
        raise ValueError('records must be a list')
    items = []
    for i, r in enumerate(recs):
        if not isinstance(r, dict):
            raise ValueError(f'record {i} must be an object')
        v = r.get('value')
        if v is None:
            continue
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            try:
                v = float(v)
            except (TypeError, ValueError):
                raise ValueError(f'record {i} has non-numeric value')
        items.append((v, r))
    if not items:
        raise ValueError('no records with a numeric value')
    items.sort(key=lambda t: -t[0])
    top = items[0][0]
    ranking = []
    for n, (v, r) in enumerate(items, 1):
        e = dict(r)
        e['value'] = v
        e['rank'] = n
        e['share_of_largest'] = (v / top) if top else None
        ranking.append(e)
    low = ranking[-1]
    ratio = (top / low['value']) if low['value'] else None
    return {'ranking': ranking, 'largest': ranking[0], 'smallest': low, 'ratio': ratio}

